-- Submapa "browser"

hl.define_submap("browser", function()
    -- help
    hl.bind("h", hl.dsp.exec_cmd("~/.config/hypr/scripts/zen_profiles.sh"))
    -- Atalhos para abrir perfis do Zen Browser
    hl.bind("p", hl.dsp.exec_cmd("zen-browser -P Pessoal"))
    hl.bind("p", hl.dsp.submap("reset"))
