    hl.bind("b", hl.dsp.submap("reset"))
    hl.bind("g", hl.dsp.exec_cmd("zen-browser -P GPT"))
    hl.bind("g", hl.dsp.submap("reset"))
    hl.bind("u", hl.dsp.exec_cmd("zen-browser -P Mateus - UFG"))
    hl.bind("u", hl.dsp.submap("reset"))
    hl.bind("w", hl.dsp.exec_cmd("zen-browser -P Work - Pacto"))
    hl.bind("w", hl.dsp.submap("reset"))
    hl.bind("z", hl.dsp.exec_cmd("zen-browser -P Whatsapp"))
    hl.bind("z", hl.dsp.submap("reset"))
    hl.bind("SHIFT" .. " + " .. "W", hl.dsp.exec_cmd("zen-browser -P Mateus - Trabalho"))
    hl.bind("W", hl.dsp.submap("reset"))
    -- Sair do modo "browser" e voltar ao padrão
    hl.bind(mainMod .. " + " .. "b", hl.dsp.submap("reset"))
    hl.bind("Return", hl.dsp.submap("reset"))
    hl.bind("Escape", hl.dsp.submap("reset"))
    -- Fim do submapa
end)


