-- Ignore maximize requests

hl.window_rule({
    name  = "nomaximize_1",
    match = {
        class = ".*",
    },
    -- TODO: review rule: "nomaximize 1"
})

-- Fix XWayland issues

hl.window_rule({
    name  = "nofocus_1",
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
})

-- SwayNC

hl.window_rule({
    name  = "opacity_1",
    match = {
        class = "^(swaync)$",
    },
    opacity = 1,
})

hl.window_rule({
    name  = "float_1",
    match = {
        class = "^(swaync)$",
    },
    -- TODO: review rule: "float 1"
})

hl.window_rule({
    name  = "center_1",
    match = {
        class = "^(swaync)$",
    },
    center = 1,
})

-- Special Workspaces

hl.window_rule({
    name  = "workspace_special_sp",
    match = {
        class = "^(spotify)$",
    },
    workspace = "special:spotify silent",
})

hl.window_rule({
    name  = "workspace_special_di",
    match = {
        class = "^(discord)$",
    },
    workspace = "special:discord silent",
})

hl.window_rule({
    name  = "workspace_special_wh",
    match = {
        class = "^(whatsdesk)$",
    },
    workspace = "special:whatsapp silent",
})

-- Standard Workspaces

hl.window_rule({
    name  = "workspace_10_silent",
    match = {
        title = "^(btop).*",
    },
    workspace = "10 silent",
})

hl.window_rule({
    name  = "workspace_1_silent",
    match = {
