-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("nm-applet &")
    hl.exec_cmd("hyprpaper &")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("waybar")
    hl.exec_cmd("kanshi &")
    hl.exec_cmd("hyprlauncher --daemon")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("swaync")
    hl.exec_cmd("hyprctl setcursor catppuccin-mocha-dark 18")
    hl.exec_cmd("spotify-launcher")
    hl.exec_cmd("discord")
    hl.exec_cmd("whatsdesk")
    hl.exec_cmd("hyprctl dispatch exec [monitor:eDP-1; workspace 1 silent] ghostty --title=main-terminal -e zsh -c 'tmux; zsh'")
    hl.exec_cmd("hyprctl dispatch exec [workspace 3 silent] zen-browser --P Pessoal")
    hl.exec_cmd("wl-paste --type text --watch cliphist store -max-items 100")
    hl.exec_cmd("wl-paste --type image --watch cliphist store -max-items 100")
    hl.exec_cmd("wl-clip-persist --clipboard both")
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
    hl.exec_cmd("dbus-update-activation-environment --systemd --all")
end)
